package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.w3c.dom.Attr
import org.w3c.dom.Element
import org.w3c.dom.Node

class RestrictionsDetector : Detector(), XmlScanner {

    override fun getApplicableElements(): Collection<String> =
        listOf(TAG_RESTRICTIONS, TAG_RESTRICTION)

    override fun visitElement(context: XmlContext, element: Element) {
        if (context.resourceFolderType != ResourceFolderType.XML) {
            return
        }
        when (element.tagName) {
            TAG_RESTRICTIONS -> validateRestrictions(context, element)
            TAG_RESTRICTION -> validateRestriction(context, element)
        }
    }

    private fun validateRestrictions(context: XmlContext, root: Element) {
        if (root.parentNode != null && root.parentNode.nodeType == Node.ELEMENT_NODE) {
            // not root? ignore
        }
        val keys = mutableSetOf<String>()
        for (child in root.directChildren(TAG_RESTRICTION)) {
            validateRestriction(context, child, keys)
        }
    }

    private fun validateRestriction(context: XmlContext, restriction: Element, keys: MutableSet<String>? = null) {
        val key = restriction.getAttribute("key")
        if (key.isBlank()) {
            report(context, restriction, "A `<restriction>` must specify a non-empty `key` attribute")
        } else if (keys != null && !keys.add(key)) {
            report(context, restriction, "Duplicate restriction key `$key`")
        }
        val title = restriction.getAttribute("title")
        if (title.isBlank()) {
            report(context, restriction, "A `<restriction>` must specify a non-empty `title` attribute")
        }
        val type = restriction.getAttribute("restrictionType")
        if (type.isBlank()) {
            report(context, restriction, "A `<restriction>` must specify a `restrictionType` attribute")
        } else if (type !in VALID_TYPES) {
            report(context, restriction, "Invalid restrictionType `$type`")
        } else {
            validateDefaultValue(context, restriction, type)
            validateChildren(context, restriction, type)
        }
    }
...
