private fun validateRestriction(context: XmlContext, restriction: Element, siblingKeys: MutableSet<String>) {
    // key
    if (!restriction.hasAttribute("key")) {
        report(context, restriction, "Missing required `key` attribute")
    } else {
        val key = restriction.getAttribute("key")
        if (key.isBlank()) report(context, restriction.getAttributeNode("key"), "Empty `key` attribute")
        else if (!siblingKeys.add(key)) report(context, restriction, "Duplicate restriction key `$key`")
    }
    // title
    if (!restriction.hasAttribute("title")) {
        report(context, restriction, "Missing required `title` attribute")
    } else if (restriction.getAttribute("title").isBlank()) {
        report(context, restriction.getAttributeNode("title"), "Empty `title` attribute")
    }
    // type
    val typeAttr = restriction.getAttributeNode("restrictionType")
    val type = if (typeAttr == null) {
        report(context, restriction, "Missing required `restrictionType` attribute")
        null
    } else {
        val v = typeAttr.value
        if (v !in VALID_TYPES) {
            report(context, typeAttr, "Invalid restrictionType `$v`")
            null
        } else v
    }
    if (type != null) {
        validateDefaultValue(context, restriction, type)
        validateChildRestrictions(context, restriction, type)
        if (type == "choice" || type == "multi_select") {
            validateChoices(context, restriction)
        }
    }
}
```

