private fun validateDefaultValue(context: XmlContext, restriction: Element, type: String) {
    if (!restriction.hasAttribute("defaultValue")) return
    val attr = restriction.getAttributeNode("defaultValue")
    val value = attr.value
    when (type) {
        "bool" -> if (value != "true" && value != "false") report(context, attr, "defaultValue for bool must be `true` or `false`")
        "integer" -> value.toIntOrNull() ?: report(context, attr, "defaultValue for integer must be a valid integer")
        "bundle", "bundle_array" -> report(context, attr, "defaultValue is not allowed for $type restrictions")
    }
}
```

