private fun validateChildRestrictions(context: XmlContext, restriction: Element, type: String) {
    val nested = restriction.directChildren(TAG_RESTRICTION)
    if (nested.isNotEmpty() && type != "bundle" && type != "bundle_array") {
        report(context, nested.first(), "Nested `<restriction>` elements are only allowed inside bundle or bundle_array restrictions")
    }
    val childKeys = mutableSetOf<String>()
    for (child in nested) {
        validateRestriction(context, child, childKeys)
    }
}
