private fun validateChoices(context: XmlContext, restriction: Element) {
    val choices = restriction.directChildren(TAG_CHOICES)
    if (choices.isEmpty()) {
        report(context, restriction, "A `${restriction.getAttribute("restrictionType")}` restriction must contain a `<choices>` element")
        return
    }
    if (choices.size > 1) {
        report(context, choices[1], "Only one `<choices>` element is allowed")
    }
    val choice = choices.first()
    val entries = choice.directChildren(TAG_ENTRY)
    val entryValues = choice.directChildren(TAG_ENTRY_VALUE)
    if (entries.isEmpty()) {
        report(context, choice, "`<choices>` must contain at least one `<entry>`")
    }
    if (entryValues.isEmpty()) {
        report(context, choice, "`<choices>` must contain at least one `<entryValue>`")
    }
    if (entries.size != entryValues.size) {
        report(context, choice, "`<entry>` and `<entryValue>` counts must match")
    }
}
