public class RestrictionsDetector extends Detector implements Detector.XmlScanner {
    private static final String TAG_RESTRICTIONS = "restrictions";
    private static final String TAG_RESTRICTION = "restriction";
    private static final String TAG_CHOICE = "choice";
    private static final String ATTR_KEY = "key";
    private static final String ATTR_TITLE = "title";
    private static final String ATTR_RESTRICTION_TYPE = "restrictionType";
    private static final String ATTR_DEFAULT_VALUE = "defaultValue";
    private static final String ATTR_VALUE = "value";
    private static final String TYPE_BOOL = "bool";
    private static final String TYPE_INTEGER = "integer";
    private static final String TYPE_CHOICE = "choice";
    private static final String TYPE_MULTI_SELECT = "multi_select";
    private static final String TYPE_HIDDEN = "hidden";
    private static final String TYPE_STRING = "string";
    private static final String TYPE_BUNDLE = "bundle";
    private static final String TYPE_BUNDLE_ARRAY = "bundle_array";
    private static final Set<String> VALID_TYPES = Sets.newHashSet(
            TYPE_BOOL, TYPE_STRING, TYPE_INTEGER, TYPE_CHOICE, TYPE_MULTI_SELECT,
            TYPE_HIDDEN, TYPE_BUNDLE, TYPE_BUNDLE_ARRAY);

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.XML;
    }

    @Nullable
    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_RESTRICTIONS);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!element.getTagName().equals(TAG_RESTRICTIONS)) {
            return;
        }
        Set<String> keys = new HashSet<>();
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (!TAG_RESTRICTION.equals(childElement.getTagName())) {
                    context.report(ISSUE, childElement, context.getLocation(childElement),
                            "Invalid element: Only `<restriction>` elements are allowed inside `<restrictions>`");
                } else {
                    checkRestriction(context, childElement, keys);
                }
            }
        }
    }

    private static void checkRestriction(XmlContext context, Element element, Set<String> keys) {
        Attr keyAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_KEY);
        if (keyAttr == null || keyAttr.getValue().isEmpty()) {
            report(context, element, "A `<restriction>` element must declare a `key` attribute");
        } else if (!keys.add(keyAttr.getValue())) {
            report(context, keyAttr, "Duplicate key `" + keyAttr.getValue() + "`");
        }
        Attr titleAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_TITLE);
        if (titleAttr == null || titleAttr.getValue().isEmpty()) {
            report(context, element, "A `<restriction>` element must declare a `title` attribute");
        }
        Attr typeAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_RESTRICTION_TYPE);
        if (typeAttr == null || typeAttr.getValue().isEmpty()) {
            report(context, element, "A `<restriction>` element must declare a `restrictionType` attribute");
        } else if (!VALID_TYPES.contains(typeAttr.getValue())) {
            report(context, typeAttr, "Invalid `restrictionType` value `" + typeAttr.getValue() + "`");
        } else {
            String type = typeAttr.getValue();
            Attr defaultValueAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_DEFAULT_VALUE);
            if (defaultValueAttr != null) {
                String defaultValue = defaultValueAttr.getValue();
                if (TYPE_BOOL.equals(type) && !defaultValue.equalsIgnoreCase("true") && !defaultValue.equalsIgnoreCase("false")) {
                    report(context, defaultValueAttr, "Default value must be `true` or `false` for boolean restrictions");
                } else if (TYPE_INTEGER.equals(type)) {
                    try { Integer.parseInt(defaultValue); } catch (NumberFormatException e) {
                        report(context, defaultValueAttr, "Default value must be an integer for integer restrictions");
                    }
                }
            }
            if (TYPE_BUNDLE.equals(type) || TYPE_BUNDLE_ARRAY.equals(type)) {
                checkNestedRestrictions(context, element);
            } else {
                // ensure no restriction children
                NodeList children = element.getChildNodes();
                for (int i = 0; i < children.getLength(); i++) {
                    Node child = children.item(i);
                    if (child.getNodeType() == Node.ELEMENT_NODE && child.getNodeName().equals(TAG_RESTRICTION)) {
                        report(context, child, "Nested `<restriction>` elements are only allowed for `bundle` or `bundle_array` types");
                    }
                }
            }
            if (TYPE_CHOICE.equals(type) || TYPE_MULTI_SELECT.equals(type)) {
                checkChoices(context, element);
            }
        }
    }

    private static void checkNestedRestrictions(XmlContext context, Element element) {
        Set<String> keys = new HashSet<>();
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (TAG_RESTRICTION.equals(childElement.getTagName())) {
                    checkRestriction(context, childElement, keys);
                } else {
                    report(context, childElement, "Only `<restriction>` elements are allowed inside `bundle`/`bundle_array` restrictions");
                }
            }
        }
    }

    private static void checkChoices(XmlContext context, Element element) {
        NodeList children = element.getChildNodes();
        boolean found = false;
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (TAG_CHOICE.equals(childElement.getTagName())) {
                    found = true;
                    Attr valueAttr = childElement.getAttributeNodeNS(ANDROID_URI, ATTR_VALUE);
                    Attr titleAttr = childElement.getAttributeNodeNS(ANDROID_URI, ATTR_TITLE);
                    if (valueAttr == null || valueAttr.getValue().isEmpty()) {
                        report(context, childElement, "A `<choice>` element must declare a `value` attribute");
                    }
                    if (titleAttr == null || titleAttr.getValue().isEmpty()) {
                        report(context, childElement, "A `<choice>` element must declare a `title` attribute");
                    }
                } else if (TAG_RESTRICTION.equals(childElement.getTagName())) {
                    // handled elsewhere
                } else {
                    report(context, childElement, "Only `<choice>` elements are allowed inside `choice`/`multi_select` restrictions");
                }
            }
        }
        if (!found) {
            report(context, element, "A `choice` or `multi_select` restriction must contain at least one `<choice>` element");
        }
    }

    private static void report(XmlContext context, Node node, String message) {
        context.report(ISSUE, node, context.getLocation(node), message);
    }

    public static final Issue ISSUE = Issue.create(
            id = "ValidRestrictions",
            briefDescription = "Invalid restrictions descriptor",
            explanation = "Ensures that an application's restrictions XML file is properly formed...",
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = new Implementation(RestrictionsDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );
}
