        context: XmlContext,
        container: Element,
        depth: Int
    ) {
        if (depth > MAX_NESTING_DEPTH) {
            report(context, container, "Restrictions cannot be nested more than $MAX_NESTING_DEPTH levels deep")
            return
        }

        val restrictionElements = container.childElements().filter { it.tagName == TAG_RESTRICTION }
        if (restrictionElements.size > MAX_NUMBER_OF_NESTED_RESTRICTIONS) {
            report(context, container, "Too many restrictions (maximum $MAX_NUMBER_OF_NESTED_RESTRICTIONS)")
        }

        val keys = mutableSetOf<String>()
        for (restriction in restrictionElements) {
            validateRestriction(context, restriction, depth, keys)
        }

        // Also report non-restriction children
        for (child in container.childElements()) {
            if (child.tagName != TAG_RESTRICTION) {
                report(context, child, "Only `<restriction>` elements are allowed inside `<${container.tagName}>`")
            }
        }
    }

    private fun validateRestriction(
        context: XmlContext,
        restriction: Element,
        depth: Int,
        keys: MutableSet<String>
    ) {
        val keyAttr = getAttr(restriction, ATTR_KEY)
        if (keyAttr == null || keyAttr.value.isEmpty()) {
            report(context, restriction, "A `<restriction>` must declare a `key` attribute")
        } else if (!keys.add(keyAttr.value)) {
            report(context, keyAttr, "Duplicate restriction key `${keyAttr.value}`")
        }

        val titleAttr = getAttr(restriction, ATTR_TITLE)
        if (titleAttr == null || titleAttr.value.isEmpty()) {
            report(context, restriction, "A `<restriction>` must declare a `title` attribute")
        }

        val typeAttr = getAttr(restriction, ATTR_RESTRICTION_TYPE)
        val type = if (typeAttr == null || typeAttr.value.isEmpty()) {
            report(context, restriction, "A `<restriction>` must declare a `restrictionType` attribute")
            null
        } else if (typeAttr.value !in VALID_TYPES) {
            report(context, typeAttr, "Invalid `restrictionType` value `${typeAttr.value}`")
            null
        } else {
            typeAttr.value
        }

        if (type != null) {
            validateDefaultValue(context, restriction, type)
            when (type) {
                TYPE_BUNDLE, TYPE_BUNDLE_ARRAY -> validateRestrictionContainer(context, restriction, depth + 1)
                TYPE_CHOICE, TYPE_MULTI_SELECT -> validateChoiceChildren(context, restriction, type)
                else -> {
                    for (child in restriction.childElements()) {
                        report(context, child, "A `<restriction>` of type `$type` must not contain child elements")
                    }
                }
            }
        }
    }
    ...
}
